public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordKey = coord -> java.util.Arrays.stream(coord)
            .mapToObj(Integer::toString)
            .reduce((a, b) -> a + "," + b)
            .orElse("");

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);

    // If start equals end
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p.length != 2 * n) {
            // Skip malformed path entries
            continue;
        }
        int[] coordA = java.util.Arrays.copyOfRange(p, 0, n);
        int[] coordB = java.util.Arrays.copyOfRange(p, n, 2 * n);
        String keyA = coordKey.apply(coordA);
        String keyB = coordKey.apply(coordB);
        adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    // BFS from start to end
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            if (visited.add(nb)) {
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

