public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }

    // Remainder 0 must have even count
    if (count[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }

    // For other remainders, count[r] must equal count[k - r]
    for (int r = 1; r < k; r++) {
        if (r == k - r) {
            // already handled when k even
            continue;
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }

    return true;
}

