private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple) {
    int time = 0;
    for (int nei : adj.get(node)) {
        if (nei == parent) continue;
        int sub = dfs(nei, node, adj, hasApple);
        if (sub > 0 || hasApple[nei]) {
            time += sub + 2;
        }
    }
    return time;
}

public String sortString(String s) {
    int[] freq = new int[65536];
    for (int i = 0; i < s.length(); i++) {
        freq[s.charAt(i)]++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        for (int c = 0; c < 65536 && remaining > 0; c++) {
            if (freq[c] > 0) {
                sb.append((char) c);
                freq[c]--;
                remaining--;
            }
        }
        for (int c = 65535; c >= 0 && remaining > 0; c--) {
            if (freq[c] > 0) {
                sb.append((char) c);
                freq[c]--;
                remaining--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int sum = 0;
    for (int num : nums) sum += num;
    // dp[k] stores all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            if (!dp[k].isEmpty()) {
                for (int s : dp[k]) {
                    dp[k + 1].add(s + num);
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((sum * k) % n != 0) continue;
        int target = (sum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0;
    if (n == 2) return Math.min(cost[0], cost[1]);

    int prev2 = cost[0];
    int prev1 = cost[1];

    for (int i = 2; i < n; i++) {
        int current = Math.min(prev1 + cost[i], prev2 + cost[i]);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

