public int minInsertions(String s) {
    int need = 0; // Count of unmatched '(' that need ')'
    int ans = 0;  // Total insertions required
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            need++;
        } else { // c == ')'
            if (need > 0) {
                need--;
            } else {
                ans++; // Insert a '(' before this ')'
            }
        }
    }
    ans += need; // Insert required ')' for remaining '('
    return ans;
}

