public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long currMax = nums[0];
    long maxSum = nums[0];
    long currMin = nums[0];
    long minSum = nums[0];
    for (int i = 1; i < nums.length; i++) {
        long val = nums[i];
        currMax = Math.max(val, currMax + val);
        maxSum = Math.max(maxSum, currMax);

        currMin = Math.min(val, currMin + val);
        minSum = Math.min(minSum, currMin);
    }
    long result = Math.max(maxSum, -minSum);
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    List<Long> fib = new ArrayList<>();
    fib.add(1L);
    fib.add(1L);
    while (true) {
        long next = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
        if (next > k) break;
        fib.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        long f = fib.get(i);
        if (f <= remaining) {
            remaining -= (int)f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> small = new ArrayList<>();
    ArrayList<Integer> large = new ArrayList<>();
    int limit = (int)Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int paired = n / i;
            if (paired != i) {
                large.add(paired);
            }
        }
    }
    // Combine small factors in ascending order and large factors in ascending order
    Collections.reverse(large);
    List<Integer> all = new ArrayList<>(small);
    all.addAll(large);
    if (k <= all.size()) {
        return all.get(k - 1);
    } else {
        return -1;
    }
}

