private void dfs(int idx, String s, java.util.Set<String> used, int[] max) {
    if (idx == s.length()) {
        if (used.size() > max[0]) {
            max[0] = used.size();
        }
        return;
    }
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, s, used, max);
            used.remove(sub);
        }
    }
}

