public String getSmallestString(int n, int k) {
    char[] arr = new char[n];
    for (int i = 0; i < n; i++) {
        arr[i] = 'a';
    }
    int remaining = k - n; // how many extra points to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // at most 'z' - 'a' = 25
        arr[i] = (char) (arr[i] + add);
        remaining -= add;
    }
    return new String(arr);
}

