        result = "-" + result;
    }
    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);

    // Precompute which pairs have a perfect square sum
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = arr[i] + arr[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                can[i][j] = true;
            }
        }
    }

    int fullMask = (1 << n) - 1;
    java.util.Map<Integer, Integer> memo = new java.util.HashMap<>();

    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            // key = mask * (n+1) + (last+1) to handle last == -1
            int key = mask * (n + 1) + (last + 1);
            Integer cached = memo.get(key);
            if (cached != null) return cached;

            if (mask == fullMask) {
                return 1;
            }

            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue; // already used
                if (last != -1 && !can[last][i]) continue; // adjacency not perfect square

                // Skip duplicates: if current number equals previous and previous hasn't been used in this state
                if (i > 0 && arr[i] == arr[i - 1] && (mask & (1 << (i - 1))) == 0) {
                    continue;
                }

                count += applyAsInt(mask | (1 << i), i);
            }

            memo.put(key, count);
            return count;
        }
    };

    return dfs.applyAsInt(0, -1);
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = 0; // number of elements in stack
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top > 0 && currentHeight < heights[stack[top - 1]]) {
            int h = heights[stack[--top]];
            int width = (top == 0) ? i : i - stack[top - 1] - 1;
            int area = h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[top++] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.max(0, sum - (n - 1));
        int endRow = Math.min(m - 1, sum);
        if (sum % 2 == 0) { // even sum -> traverse from endRow down to startRow
            for (int i = endRow; i >= startRow; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else { // odd sum -> traverse from startRow up to endRow
            for (int i = startRow; i <= endRow; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    long result = Long.parseLong(new String(digits));
    if (result > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    return build(n, n);
}

private static List<String> build(int remaining, int total) {
    if (remaining == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (remaining == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }

    List<String> sub = build(remaining - 2, total);
    List<String> result = new ArrayList<>();
    char[][] pairs = {
        {'0', '0'},
        {'1', '1'},
        {'6', '9'},
        {'8', '8'},
        {'9', '6'}
    };

    for (String s : sub) {
        for (char[] pair : pairs) {
            if (remaining == total && pair[0] == '0') {
                continue; // avoid leading zero
            }
            StringBuilder sb = new StringBuilder();
            sb.append(pair[0]).append(s).append(pair[1]);
            result.add(sb.toString());
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check for duplicate points
    if (x1 == x2 && y1 == y2) return false;
    if (x1 == x3 && y1 == y3) return false;
    if (x2 == x3 && y2 == y3) return false;

    // Calculate the signed area (cross product)
    int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);

    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == prev) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
            prev = c;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>(n);
    long cur = 1;
    while (res.size() < n) {
        res.add((int) cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur += 1;
        } else {
            while ((cur / 10) % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur += 1;
        }
    }
    return res;
}

public static int calculateUniqueSum(int[] nums) {
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int minCount = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < minCount) {
                minCount = candidate;
            }
        }
        dp[i] = minCount;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
